using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.NTF.NotificacionesVisualizadas;namespace GraphApi.Services.NTF.NotificacionesVisualizadas{    public class NotificacionesVisualizadasService : INotificacionesVisualizadasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public NotificacionesVisualizadasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadNotificacionesVisualizadas>> GetNotificacionesVisualizadas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM ntf.NotificacionesVisualizadas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadNotificacionesVisualizadas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetNotificacionesVisualizadasDynamic(            int? notificacionVisualizadaID,            int? notificacionID,            int? usuarioID,            DateTime? fechaLectura,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "NotificacionVisualizadaID, NotificacionID, UsuarioID, FechaLectura, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM ntf.NotificacionesVisualizadas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (notificacionVisualizadaID.HasValue)            {                vSql.Append(" AND NotificacionVisualizadaID = @NotificacionVisualizadaID");                vParameters.Add("NotificacionVisualizadaID",notificacionVisualizadaID);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadNotificacionesVisualizadas> CreateNotificacionesVisualizadas(clCreateNotificacionesVisualizadas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO ntf.NotificacionesVisualizadas                (NotificacionID, UsuarioID, FechaLectura, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@NotificacionID, @UsuarioID, @FechaLectura, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.NotificacionID,                objInput.UsuarioID,                objInput.FechaLectura,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT NotificacionVisualizadaID, NotificacionID, UsuarioID, FechaLectura, bEliminado                FROM ntf.NotificacionesVisualizadas (NOLOCK)                WHERE NotificacionVisualizadaID = @NotificacionVisualizadaID;";            var vReadParams = new { NotificacionVisualizadaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadNotificacionesVisualizadas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el NotificacionesVisualizada con ID {vNewId}.");            return vCreated;        }        public async Task<clReadNotificacionesVisualizadas?> UpdateNotificacionesVisualizadas(clUpdateNotificacionesVisualizadas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("NotificacionVisualizadaID", objInput.NotificacionVisualizadaID);            if (objInput.NotificacionID != null)            {                vSets.Add("NotificacionID = @NotificacionID");                vParameters.Add("NotificacionID", objInput.NotificacionID);            }            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.FechaLectura != null)            {                vSets.Add("FechaLectura = @FechaLectura");                vParameters.Add("FechaLectura", objInput.FechaLectura);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE ntf.NotificacionesVisualizadas                SET {vSetClause}                WHERE NotificacionVisualizadaID = @NotificacionVisualizadaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT NotificacionVisualizadaID, NotificacionID, UsuarioID, FechaLectura, bEliminado                FROM ntf.NotificacionesVisualizadas (NOLOCK)                WHERE NotificacionVisualizadaID = @NotificacionVisualizadaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadNotificacionesVisualizadas>(sSelect, new {  objInput.NotificacionVisualizadaID });        }        public async Task<bool> DeleteNotificacionesVisualizadas(int nNotificacionesVisualizadasID)        {            const string sSql = @"                DELETE FROM ntf.NotificacionesVisualizadas                WHERE NotificacionVisualizadaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nNotificacionesVisualizadasID });            return vAffected > 0;        }    }}